previewCss:
.darma-loader-darma-b10-tunnel-squares { --accent: var(--loader-color, #06b6d4); --accent-2: var(--loader-secondary-color, #d946ef); width: var(--loader-size, 80px); height: var(--loader-size, 80px); position: relative; }
.darma-loader-darma-b10-tunnel-squares span { position: absolute; inset: 0; border: calc(var(--loader-size, 80px) * .035) solid var(--accent); border-radius: 10%; animation: darma-loader-darma-b10-tunnel-squares-tunnel calc(var(--loader-speed, 1s) * 2.4) linear infinite; }
.darma-loader-darma-b10-tunnel-squares span:nth-child(even) { border-color: var(--accent-2); }
.darma-loader-darma-b10-tunnel-squares span:nth-child(2) { animation-delay: calc(var(--loader-speed, 1s) * -.6); }
.darma-loader-darma-b10-tunnel-squares span:nth-child(3) { animation-delay: calc(var(--loader-speed, 1s) * -1.2); }
.darma-loader-darma-b10-tunnel-squares span:nth-child(4) { animation-delay: calc(var(--loader-speed, 1s) * -1.8); }
@keyframes darma-loader-darma-b10-tunnel-squares-tunnel { 0% { transform: scale(1) rotate(0deg); opacity: 0; } 15% { opacity: 1; } 100% { transform: scale(.05) rotate(90deg); opacity: 0; } }

